PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?later ?laterLabel ?laterBirth WHERE {
  VALUES (?p1 ?p2) { (dbr:Levon_Julfalakyan dbr:Charlotte_Spurkeland) }

  OPTIONAL { ?p1 dbo:birthDate ?b1 } 
  OPTIONAL { ?p1 dbp:birthDate ?b1b }
  OPTIONAL { ?p2 dbo:birthDate ?b2 } 
  OPTIONAL { ?p2 dbp:birthDate ?b2b }

  BIND(COALESCE(?b1, ?b1b) AS ?bd1)
  BIND(COALESCE(?b2, ?b2b) AS ?bd2)

  {
    FILTER(BOUND(?bd1) && BOUND(?bd2) && (?bd1 > ?bd2))
    BIND(?p1 AS ?later)
    BIND(?bd1 AS ?laterBirth)
  }
  UNION
  {
    FILTER(BOUND(?bd1) && BOUND(?bd2) && (?bd2 > ?bd1))
    BIND(?p2 AS ?later)
    BIND(?bd2 AS ?laterBirth)
  }

  OPTIONAL { ?later rdfs:label ?laterLabel . FILTER(langMatches(lang(?laterLabel), "en")) }
}

